"use strict";
// Inert bypass probes. Each probe tries to reach the real fs without going through the
// per-package wrapper and reports what it got. Nothing here touches the network.
const Module = require("module");

module.exports = function probes(realFs) {
  const out = {};
  // true = the probe got the real (unwrapped) fs module.
  const same = (x) => x === realFs;

  out.requireResolve = require.resolve("fs");
  out.createRequire = same(Module.createRequire(__filename)("fs"));
  out.dynamicImport = import("node:fs").then((ns) => same(ns.default));
  out.getBuiltinModule = same(process.getBuiltinModule("fs"));
  out.mainModuleRequire = process.mainModule ? same(process.mainModule.require("fs")) : "no mainModule (ESM entry)";
  // oxlint-disable-next-line no-underscore-dangle -- probing the private loader on purpose
  out.moduleLoad = same(Module._load("fs", null, false));
  try {
    const binding = process.binding("fs");
    out.processBinding = typeof binding.open === "function" ? "raw binding reachable" : "no";
  } catch (e) {
    out.processBinding = "threw: " + e.message;
  }
  out.requireCacheKeys = Object.keys(require.cache).filter((k) => k.startsWith("depward-cap:")).length;
  return out;
};
